import { lazy } from 'react'

import { ItemCard } from '~/ui/layout/item/ItemCard'
import { VideoView } from '~/ui/parts/VideoView'
import type { CommonCardProp } from '~/ui/items/common'

import { name } from './name'

import videoNormal from './normal.mp4'
import videoSmall from './small.mp4'
import thumbnailP from './thumbnail.jpg'
import thumbnailM from './thumbnail.mp4'

const Explanation = lazy(() => import('./Explanation'));


type Prop = CommonCardProp & {
  id: string;
}
export default function AutoDoorDoubleLeaf(prop: Prop) {
  const { openDrawer, ...otherProp } = prop;
  
  return (
    <ItemCard
      {...otherProp}
      content={<VideoView
        videoNormal={videoNormal}
        videoSmall={videoSmall}
        thumbnailP={thumbnailP}
        thumbnailM={thumbnailM}
        />}
      title={<>{name.title}</>}
      level={3.0}
      >
      <Explanation openDrawer={openDrawer} />
    </ItemCard>
  )
}

